import { html } from "../../../../html.js";
import { useState } from "/prototype/vendor/preact-hooks.js";
import { Dialog, Icon, StatusPill } from "../../ui/index.js";
import PageVariants from "../../ui/PageVariants.js";

const requests=[
 {id:"retry",title:"Add jittered retry policy",org:"acme-platform",agent:"atlas",repo:"durable/web",pr:"#412",sha:"9f3c2ab",ci:"passing",review:"approved",risk:"medium",expires:"12m",reason:"Protected branch · retry behavior",device:"YubiKey 5C NFC"},
 {id:"ledger",title:"Reconcile settlement ledger",org:"acme-platform",agent:"beacon",repo:"payments/service",pr:"#188",sha:"a18d02c",ci:"passing",review:"approved",risk:"high",expires:"28m",reason:"Payment boundary · write access",device:"MacBook Pro Touch ID"},
 {id:"parser",title:"Fix parser diagnostic spans",org:"oss-maintenance",agent:"forge",repo:"open-source/cli",pr:"#928",sha:"bd7fe10",ci:"passing",review:"approved",risk:"low",expires:"41m",reason:"Public release branch",device:"YubiKey 5C NFC"},
 {id:"release",title:"Publish 1.8 release notes",org:"acme-platform",agent:"atlas",repo:"durable/web",pr:"#419",sha:"f7a912e",ci:"running",review:"pending",risk:"medium",expires:"1h 04m",reason:"Release workflow · external publish",device:"Platform passkey"}
];
const history=[
 ["10:42", "Approved", "Fix parser diagnostic spans", "N. Rivera · YubiKey 5C NFC"],
 ["09:18", "Held", "Reconcile settlement ledger", "N. Rivera · policy changed"],
 ["Yesterday", "Released", "Rotate webhook fixture", "A. Chen · MacBook Pro Touch ID"]
];
function Risk({value}){return html`<span class=${`p-approvals-risk ${value}`}>${value} risk</span>`}
function Toast({children}){return children&&html`<div class="p-approvals-toast" role="status">${children}</div>`}
function RequestRow({item,selected,onSelect,compact=false}){return html`<button class=${`p-approvals-request ${selected?'selected':''} ${compact?'compact':''}`} onClick=${()=>onSelect(item)} aria-pressed=${selected}><span class="p-approvals-risk-dot ${item.risk}"></span><span class="p-approvals-request-main"><strong>${item.title}</strong><small>${item.org} / ${item.repo} · ${item.pr} · <code>${item.sha}</code></small></span><span class="p-approvals-request-meta"><${StatusPill} status=${item.ci}/><small>expires ${item.expires}</small></span></button>`}
function Policy({item}){return html`<section class="p-approvals-policy"><div><span class="p-approvals-eyebrow">Why this is gated</span><strong>Two independent checks require a human passkey.</strong></div><ul><li>Protected branch policy applies to <code>${item.repo}</code></li><li>${item.reason}</li><li>CI and review verdict are bound to <code>${item.sha}</code></li></ul><button class="p-approvals-link">View policy P-17 <${Icon} name="arrow-up-right"/></button></section>`}
function ActionBar({selected,onAction}){return html`<div class="p-approvals-actions"><button onClick=${()=>onAction("Held for 30 minutes")}>Hold</button><button onClick=${()=>onAction("Batch staged — passkey required")}>Batch</button><button class="p-approvals-primary" onClick=${()=>onAction(`Approval requested for ${selected.title}`)}>Approve with passkey</button></div>`}
function QueueVariant(){const [filter,setFilter]=useState("All orgs");const [selected,setSelected]=useState(requests[0]);const [toast,setToast]=useState("");const visible=filter==="All orgs"?requests:requests.filter(x=>x.org===filter);const action=x=>{setToast(x);setTimeout(()=>setToast(""),2600)};return html`<section class="p-approvals-screen p-approvals-queue"><header class="p-approvals-header"><div><span class="p-approvals-eyebrow">Passkey control plane</span><h1>Approval queue <b>${visible.length}</b></h1><p>Changes pause at the trust boundary until a verified operator releases them.</p></div><div class="p-approvals-header-actions"><button onClick=${()=>action("Enrollment code copied")}>+ Enroll device</button><button class="p-approvals-icon-button" aria-label="Approval settings"><${Icon} name="settings"/></button></div></header><div class="p-approvals-toolbar"><div class="p-approvals-filter" role="group" aria-label="Organization filter">${["All orgs","acme-platform","oss-maintenance"].map(x=>html`<button class=${filter===x?'on':''} onClick=${()=>setFilter(x)}>${x}</button>`)}</div><span>4 need a decision · next SLA <strong>12m</strong></span></div><div class="p-approvals-queue-grid"><section class="p-approvals-list" aria-label="Pending approvals">${visible.map(item=>html`<${RequestRow} item=${item} selected=${selected.id===item.id} onSelect=${setSelected}/>`)}<button class="p-approvals-show-more" onClick=${()=>action("Showing held requests")}>Show 2 held requests</button></section><aside class="p-approvals-summary"><div class="p-approvals-summary-title"><span class="p-approvals-eyebrow">Selected change</span><${Risk} value=${selected.risk}/></div><h2>${selected.title}</h2><p>${selected.agent} proposes ${selected.pr} on <code>${selected.sha}</code>.</p><div class="p-approvals-facts"><span>CI <b>${selected.ci}</b></span><span>Review <b>${selected.review}</b></span><span>Expiry <b>${selected.expires}</b></span></div><${Policy} item=${selected}/><${ActionBar} selected=${selected} onAction=${action}/></aside></div><section class="p-approvals-bottom-grid"><div class="p-approvals-card"><span class="p-approvals-eyebrow">On-call coverage</span><strong>1 of 2 passkey operators active</strong><p>Escalate to A. Chen in 8m if no decision lands.</p></div><div class="p-approvals-card"><span class="p-approvals-eyebrow">Batch guardrail</span><strong>Same repo + policy only</strong><p>3 requests are eligible for one verified approval.</p></div></section><${Toast}>${toast}</${Toast}></section>`}
function ReviewVariant(){const [item,setItem]=useState(requests[1]);const [tab,setTab]=useState("Diff");const [dialog,setDialog]=useState(false);const [toast,setToast]=useState("");const action=x=>{setDialog(false);setToast(x);setTimeout(()=>setToast(""),2600)};return html`<section class="p-approvals-screen p-approvals-review"><header class="p-approvals-review-top"><div><button class="p-approvals-back" onClick=${()=>setItem(requests[(requests.indexOf(item)+1)%requests.length])}>‹ Next request</button><h1>${item.title}</h1><p>${item.org} · ${item.repo} <code>${item.sha}</code> · ${item.pr}</p></div><div><${Risk} value=${item.risk}/><span class="p-approvals-expiry">Decision window ${item.expires}</span></div></header><div class="p-approvals-review-layout"><aside class="p-approvals-review-rail"><span class="p-approvals-eyebrow">Pending</span>${requests.map(x=>html`<${RequestRow} item=${x} compact=${true} selected=${x.id===item.id} onSelect=${setItem}/>`)}<button class="p-approvals-link">View audit trail</button></aside><main class="p-approvals-diff"><div class="p-approvals-tabs">${["Diff","Checks","Agent plan"].map(x=>html`<button class=${tab===x?'on':''} onClick=${()=>setTab(x)}>${x}</button>`)}</div>${tab==="Diff"?html`<div class="p-approvals-code" aria-label="Code diff"><div><b>src/retry/backoff.ts</b><span>+18 −3</span></div><pre><i>  14</i> export function delay(attempt: number) {
<i class="add">+ 15</i><em>+  const jitter = Math.random() * 0.2 + 0.9;</em>
<i>  16</i>   const base = Math.min(30_000, 2 ** attempt * 100);
<i class="add">+ 17</i><em>+  return Math.round(base * jitter);</em>
<i>  18</i> }</pre></div>`:html`<div class="p-approvals-empty-panel"><strong>${tab}</strong><p>${tab==="Checks"?"CI passes; review is approved; no policy exceptions.":"Agent will add bounded jitter, update the focused test, and stop."}</p></div>`}</main><aside class="p-approvals-verdict"><span class="p-approvals-eyebrow">Verdict</span><h2>Safe to release?</h2><div class="p-approvals-verdict-row"><span>CI</span><b>Passing</b></div><div class="p-approvals-verdict-row"><span>Review</span><b>Approved</b></div><div class="p-approvals-verdict-row"><span>Blast radius</span><b>2 services</b></div><${Policy} item=${item}/><button class="p-approvals-primary" onClick=${()=>setDialog(true)}>Verify passkey & approve</button><button onClick=${()=>action("Request returned to agent with a note")}>Return with note</button></aside></div>${dialog&&html`<${Dialog} onClose=${()=>setDialog(false)}><div class="p-approvals-dialog"><span class="p-approvals-eyebrow">Passkey verification</span><h2>Approve ${item.pr}?</h2><p>Use <strong>${item.device}</strong>. This signature binds the reviewed SHA and policy P-17.</p><button class="p-approvals-primary" onClick=${()=>action("Passkey verified — agent released")}>Use passkey</button><button onClick=${()=>setDialog(false)}>Cancel</button></div></${Dialog}>`}<${Toast}>${toast}</${Toast}></section>`}
function GovernanceVariant(){const [tab,setTab]=useState("Audit trail");const [toast,setToast]=useState("");const action=x=>{setToast(x);setTimeout(()=>setToast(""),2600)};return html`<section class="p-approvals-screen p-approvals-governance"><header class="p-approvals-header"><div><span class="p-approvals-eyebrow">Approval governance</span><h1>Trust posture</h1><p>Every release decision is attributable to a person, device, SHA, and policy.</p></div><div class="p-approvals-posture"><span>Fleet trust</span><strong>Healthy</strong><small>3 enrolled passkeys · 0 exceptions</small></div></header><div class="p-approvals-governance-grid"><section class="p-approvals-audit"><div class="p-approvals-tabs">${["Audit trail","Policies","Devices"].map(x=>html`<button class=${tab===x?'on':''} onClick=${()=>setTab(x)}>${x}</button>`)}</div>${tab==="Audit trail"?html`<ol class="p-approvals-timeline">${history.map(([time,event,title,by])=>html`<li><time>${time}</time><span class=${event==="Held"?"wait":"done"}></span><div><strong>${event} · ${title}</strong><small>${by}</small></div></li>`)}</ol>`:tab==="Policies"?html`<div class="p-approvals-policy-list"><strong>P-17 Protected release</strong><p>Passkey approval is required for protected branches, payment boundaries, and external publishing.</p><strong>P-08 Batch equivalence</strong><p>Only identical repo and policy scopes can share a decision.</p></div>`:html`<div class="p-approvals-device-list"><div><strong>YubiKey 5C NFC</strong><span>Last used 10:42 · hardware-backed</span></div><div><strong>MacBook Pro Touch ID</strong><span>Last used yesterday · platform passkey</span></div><button onClick=${()=>action("Enrollment code generated: FLEET-7KQ")}>Generate enrollment code</button></div>`}</section><aside class="p-approvals-posture-card"><span class="p-approvals-eyebrow">SLA & risk</span><div class="p-approvals-score"><strong>82</strong><span>/100</span><small>Fleet release confidence</small></div><div class="p-approvals-meter"><i></i></div><ul><li><b>4</b> decisions awaiting operator</li><li><b>12m</b> nearest expiry</li><li><b>0</b> policy exceptions this week</li></ul><button class="p-approvals-primary" onClick=${()=>action("On-call escalation preview opened")}>Set escalation</button></aside></div><section class="p-approvals-recovery"><div><span class="p-approvals-eyebrow">Incident-ready control</span><strong>Freeze approvals across a single organization</strong><p>Stops new releases without interrupting active agent work.</p></div><button onClick=${()=>action("Organization freeze requires confirmation")}>Prepare freeze</button></section><${Toast}>${toast}</${Toast}></section>`}
export default function ApprovalsPage(){return html`<main class="e-page p-approvals-page"><${PageVariants} variants=${[{key:"1",name:"Queue",render:()=>html`<${QueueVariant}/>`},{key:"2",name:"Review",render:()=>html`<${ReviewVariant}/>`},{key:"3",name:"Governance",render:()=>html`<${GovernanceVariant}/>`}]}/></main>`}
